import{c as a,Q as e,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Improving Factuality and Reasoning in Language Models through Multiagent Debate","description":"","frontmatter":{"url":"https://arxiv.org/abs/2305.14325","title":"Improving Factuality and Reasoning in Language Models through Multiagent Debate","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2305.14325,"authors":["Yilun Du","Shuang Li","Antonio Torralba","Joshua B. Tenenbaum","Igor Mordatch"],"domains":["cs.CL","cs.AI"],"pdf_path":"pdfs/2305.14325.pdf","published_date":"2023-05-23T00:00:00.000Z","tags":["multi-agent","debate","reasoning","factuality","hallucination","llm"]},"headers":[],"relativePath":"research/papers/2023-05-23-multiagent-debate-factuality-reasoning-2305-14325.md","filePath":"research/papers/2023-05-23-multiagent-debate-factuality-reasoning-2305-14325.md","lastUpdated":1785909234000}'),r={name:"research/papers/2023-05-23-multiagent-debate-factuality-reasoning-2305-14325.md"};function o(s,t,l,d,g,u){return e(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="improving-factuality-and-reasoning-in-language-models-through-multiagent-debate" tabindex="-1">Improving Factuality and Reasoning in Language Models through Multiagent Debate <a class="header-anchor" href="#improving-factuality-and-reasoning-in-language-models-through-multiagent-debate" aria-label="Permalink to &quot;Improving Factuality and Reasoning in Language Models through Multiagent Debate&quot;">​</a></h1><p><strong>arXiv</strong>: 2305.14325 | <strong>發表</strong>: 2023-05-23 | <strong>PDF</strong>: 2023-05-23-multiagent-debate-factuality-reasoning-2305-14325.pdf</p><h2 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h2><p>Du et al.（MIT / Google）提出「Society of Minds」多 agent 辯論機制：多個 LLM 實例對同一問題獨立作答，再互相閱讀答案並更新自己的回應，迭代多輪至收斂。核心假設：多視角辯論能比單 agent 更有效地消除幻覺並提升推理一致性。</p><h2 id="方法-架構" tabindex="-1">方法 / 架構 <a class="header-anchor" href="#方法-架構" aria-label="Permalink to &quot;方法 / 架構&quot;">​</a></h2><ul><li><strong>辯論設定</strong>：N 個獨立 LLM agents（同模型），各自先獨立作答</li><li><strong>迭代輪次</strong>：每輪每個 agent 閱讀其他 agents 的答案後更新自己的回應，共 T 輪（通常 T=3）</li><li><strong>收斂判斷</strong>：多數一致視為終態；無需外部裁判（self-organizing consensus）</li><li><strong>黑盒相容</strong>：只需 prompt-in / answer-out，不需模型微調或內部修改</li><li><strong>零額外訓練成本</strong>：可直接部署於現有 LLM API（實驗使用 ChatGPT）</li></ul><h2 id="關鍵發現與數據-ar5iv-抓取-數據已核實" tabindex="-1">關鍵發現與數據（ar5iv 抓取，數據已核實） <a class="header-anchor" href="#關鍵發現與數據-ar5iv-抓取-數據已核實" aria-label="Permalink to &quot;關鍵發現與數據（ar5iv 抓取，數據已核實）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任務</th><th>單 Agent</th><th>多 Agent 辯論</th><th>提升</th></tr></thead><tbody><tr><td>Arithmetic</td><td>67.0% ± 4.7</td><td>81.8% ± 2.3</td><td>+14.8pp</td></tr><tr><td>GSM8K</td><td>77.0% ± 4.2</td><td>85.0% ± 3.5</td><td>+8.0pp</td></tr><tr><td>MMLU</td><td>63.9% ± 4.8</td><td>71.1% ± 4.6</td><td>+7.2pp</td></tr><tr><td>Biography factuality</td><td>66.0% ± 2.2</td><td>73.8% ± 2.3</td><td>+7.8pp</td></tr><tr><td>Chess move validity</td><td>29.3% ± 2.6</td><td>45.2% ± 2.9</td><td>+15.9pp</td></tr></tbody></table><h2 id="對-agent-team-設計的啟示" tabindex="-1">對 agent-team 設計的啟示 <a class="header-anchor" href="#對-agent-team-設計的啟示" aria-label="Permalink to &quot;對 agent-team 設計的啟示&quot;">​</a></h2><ol><li><strong>辯論是免訓練的推理增強</strong>：對複雜推理任務可以直接在 inference 時疊加 debate round，無需更強的模型</li><li><strong>任務類型影響效益</strong>：arithmetic / factual 任務提升明顯（+8~15pp）；過度簡單或過度複雜任務效益遞減</li><li><strong>收斂失敗是風險</strong>：若多 agent 形成錯誤共識（echo chamber），辯論反而固化錯誤——需設計 diversity preservation 機制（呼應 AgentVerse groupthink 問題）</li></ol><h2 id="原文關鍵引用-≤150字" tabindex="-1">原文關鍵引用（≤150字） <a class="header-anchor" href="#原文關鍵引用-≤150字" aria-label="Permalink to &quot;原文關鍵引用（≤150字）&quot;">​</a></h2><blockquote><p>&quot;We propose a method where multiple language model instances propose and debate their individual responses and reasoning processes over multiple rounds to arrive at a common final answer. Our findings suggest that this approach significantly enhances mathematical and strategic reasoning across several benchmarks while improving the factual validity of generated content, reducing fallacious answers and hallucinations... Our approach also applies to black-box models using identical prompts across all tasks.&quot;</p></blockquote>',12)])])}const p=a(r,[["render",o]]);export{c as __pageData,p as default};
